    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello Utkarsh जी आपकी Berinut injection human C1 esterase inhibitor 500 IU की request IndiaMART पर raise है।"
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "बस उसी के लिए कुछ details confirm करनी थी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "उत्कर्ष जी क्या आप line पर हैं?"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "चलिए अब brand के बारे में बात कर लेते हैं आपको कौन सा चाहिए Alergen या कुछ और?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "and everything."
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "जी मैं यहीं हूँ।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "बताइए brand में आप क्या prefer करेंगे?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "Allergen Bharat serum या कोई और?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "seller भारत से या कोई और कुछ भी चलेगा।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "अब volume के बारे में बात कर लेते हैं।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए जैसे 100 milliliter, 10 milliliter या कुछ और?"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "सौ एमएम दस एमएम जो मिल जाए मुझे available कीजिए।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "ठीक है 10 millilitres note कर लिया है।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "क्या आप इस product के बारे में कोई और details या specification share करना चाहेंगे?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "मुझे बहुत दर्द नहीं है क्योंकि मुझे हर तरह से inquiry demand है।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "मैं समझ सकता हूं।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "आपकी details note कर ली गई हैं और जल्द ही एक seller आपसे contact करेंगे।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
